insert into categories (slug, name, description, sort_order, icon) values
  ('tags-labels', 'Tags & Labels', 'Choose the RFID tag by the surface it sits on and where it lives: paper labels for cartons and files, on-metal tags for equipment, rugged tags for outdoor assets.', 1, 'tag'),
  ('readers-antennas', 'Readers & Antennas', 'Handheld readers for counting and finding items; fixed readers and antennas for gates, dock doors and conveyors that read tags automatically.', 2, 'radio'),
  ('barcode-scanners', 'Barcode Scanners', 'Barcode and QR scanners are a low-cost way to track stock, parcels and documents. Pick by where you scan: at a desk, on the move or on a conveyor.', 3, 'scan'),
  ('printers-encoders', 'Printers & Encoders', 'Print and encode your own RFID and barcode labels in-house, from a few labels a day to thousands, with the matching labels and ribbons.', 4, 'printer'),
  ('edge-iot', 'Edge & IoT Devices', 'Edge AI boxes and industrial gateways for projects that need computing on site. Sold by quote with set-up support from our engineers.', 5, 'cpu')
on conflict (slug) do nothing;

insert into products (sku, slug, name, brand, category_id, short_description, long_description, specs, images, price_paise, gst_percent, hsn_code, stock_qty, min_order_qty, is_active, is_featured, quote_only, seo_title, seo_description) values
  ('PI-TAG-001', 'uhf-rfid-paper-labels', 'UHF RFID Paper Labels (Self-Adhesive)', 'Prosper Infotech', (select id from categories where slug = 'tags-labels'), 'Cartons, files, boxes, documents and retail stock.', 'UHF RFID paper labels are the most economical way to tag items that are not metal: cartons, files, boxes, documents and retail stock. Each label carries an EPC Gen2 (ISO 18000-6C) chip, so it can be read by any standard UHF RFID reader, many at a time and without line of sight.

The labels are self-adhesive and supplied on rolls or sheets. They can be printed and encoded on an RFID printer, or used blank. For metal surfaces, choose on-metal tags instead.', '[{"label":"Frequency","value":"UHF 860-960 MHz"},{"label":"Standard","value":"EPC Gen2 / ISO 18000-6C"},{"label":"Format","value":"Self-adhesive label, roll or sheet"},{"label":"Surface","value":"Paper, cardboard, plastic"}]'::jsonb, '["/shop/products/uhf-paper-labels.jpg"]'::jsonb, null, 18, '', 0, 1, true, true, false, 'UHF RFID Paper Labels – Self-Adhesive | Prosper', 'Self-adhesive UHF RFID paper labels (EPC Gen2) for cartons, files, boxes and retail stock. Roll or sheet. Buy online with GST invoice across India.'),
  ('PI-TAG-002', 'on-metal-rfid-tags', 'UHF On-Metal RFID Tags', 'Prosper Infotech', (select id from categories where slug = 'tags-labels'), 'IT equipment, tools, machines, racks and metal cabinets.', 'Ordinary RFID labels stop working when stuck directly on metal. On-metal RFID tags are built to read reliably on metal and mixed surfaces, which makes them the right choice for IT equipment, tools, machines, racks and metal cabinets.

The tags use EPC Gen2 (ISO 18000-6C) UHF chips and fix with adhesive or screws. They work with handheld and fixed UHF RFID readers and with Prosper Asset Tracking.', '[{"label":"Frequency","value":"UHF 860-960 MHz"},{"label":"Standard","value":"EPC Gen2 / ISO 18000-6C"},{"label":"Format","value":"Hard tag, adhesive or screw mount"},{"label":"Surface","value":"Metal and mixed surfaces"}]'::jsonb, '[]'::jsonb, null, 18, '', 0, 1, true, false, false, 'UHF On-Metal RFID Tags for Equipment | Prosper', 'UHF on-metal RFID tags for IT equipment, tools, machines and racks. Adhesive or screw mount, EPC Gen2. Buy online with GST invoice in India.'),
  ('PI-TAG-003', 'rugged-outdoor-rfid-tags', 'Rugged Outdoor UHF RFID Tags', 'Prosper Infotech', (select id from categories where slug = 'tags-labels'), 'Containers, trailers, pallets, cylinders and yard assets.', 'Rugged outdoor RFID tags are made for assets that live outside or take knocks: containers, trailers, pallets, gas cylinders and yard equipment. The hard housing resists weather, UV and impact, so the tag keeps reading for years.

They mount with bolts or straps and read with UHF RFID readers at gates and yards, making them a good fit for yard management and asset tracking projects.', '[{"label":"Frequency","value":"UHF 860-960 MHz"},{"label":"Durability","value":"Weather, UV and impact resistant"},{"label":"Format","value":"Hard tag, bolt or strap mount"},{"label":"Use","value":"Indoor and outdoor"}]'::jsonb, '["/shop/products/rugged-outdoor-tags.jpg"]'::jsonb, null, 18, '', 0, 1, true, true, false, 'Rugged Outdoor UHF RFID Tags | Prosper Infotech', 'Weather, UV and impact resistant UHF RFID tags for containers, trailers, pallets and yard assets. Bolt or strap mount. Delivery across India.'),
  ('PI-TAG-004', 'cable-tie-and-hang-tags', 'RFID Cable-Tie and Hang Tags', 'Prosper Infotech', (select id from categories where slug = 'tags-labels'), 'Garments, bags, cables, tools and items with no flat surface.', 'Some items have no flat surface for a label. RFID cable-tie and hang tags attach by looping around the item, which suits garments, bags, cables, hoses and hand tools.

The tags carry EPC Gen2 UHF chips and are available in reusable and single-use versions, so you can tag items permanently or only while they are in your process.', '[{"label":"Frequency","value":"UHF 860-960 MHz"},{"label":"Standard","value":"EPC Gen2 / ISO 18000-6C"},{"label":"Format","value":"Cable-tie or hang tag"},{"label":"Use","value":"Reusable or single use"}]'::jsonb, '[]'::jsonb, null, 18, '', 0, 1, true, false, false, 'RFID Cable-Tie & Hang Tags (UHF) | Prosper Infotech', 'UHF RFID cable-tie and hang tags for garments, bags, cables and tools with no flat surface. Reusable or single use. Buy online across India.'),
  ('PI-RDR-001', 'handheld-uhf-rfid-reader', 'Handheld UHF RFID Reader (Android)', 'Prosper Infotech', (select id from categories where slug = 'readers-antennas'), 'Stock counts, audits, asset checks and finding a missing item.', 'A handheld UHF RFID reader turns a stock count that takes a day into one that takes minutes: walk past shelves and the reader picks up every tag in range. It is also the quickest way to audit assets or find a missing item.

This reader runs Android, has a pistol-grip trigger and connects over Wi-Fi and Bluetooth, with optional 4G. It runs the Prosper Asset Tracking app, so counts and audits sync straight to your system.', '[{"label":"Frequency","value":"UHF 860-960 MHz"},{"label":"Platform","value":"Android handheld with trigger"},{"label":"Connectivity","value":"Wi-Fi, Bluetooth, optional 4G"},{"label":"Works with","value":"Prosper Asset Tracking app"}]'::jsonb, '["/shop/products/handheld-uhf-reader.jpg"]'::jsonb, null, 18, '', 0, 1, true, true, false, 'Handheld UHF RFID Reader – Android | Prosper Infotech', 'Android handheld UHF RFID reader with trigger for stock counts, audits and finding missing items. Wi-Fi, Bluetooth, optional 4G. Delivery in India.'),
  ('PI-RDR-002', '4-port-fixed-rfid-reader', '4-Port Fixed UHF RFID Reader (Impinj E710)', 'Prosper Infotech', (select id from categories where slug = 'readers-antennas'), 'Gates, dock doors, conveyors and portals with continuous reads.', 'A fixed RFID reader reads tags automatically as they pass, with no one holding a scanner. This industrial reader is built on the Impinj E710 chip, reads more than 1,000 tags per second and drives up to four antennas, enough to cover a gate, dock door, conveyor or portal.

It runs on DC 12V or Power over Ethernet. Our RFID services team can plan antenna placement, install the reader and connect it to your software.', '[{"label":"RF Chip","value":"Impinj E710"},{"label":"Read Speed","value":"1000+ tags per second"},{"label":"Ports","value":"4 antenna ports"},{"label":"Power","value":"DC 12V or PoE"}]'::jsonb, '["/shop/products/fixed-rfid-reader.jpg"]'::jsonb, null, 18, '', 0, 1, true, true, false, '4-Port Fixed UHF RFID Reader – Impinj E710 | Prosper', 'Industrial 4-port fixed UHF RFID reader on Impinj E710, 1000+ tags per second, PoE or 12V. For gates, dock doors and conveyors. Delivery in India.'),
  ('PI-RDR-003', 'rfid-antennas', 'UHF RFID Antennas', 'Prosper Infotech', (select id from categories where slug = 'readers-antennas'), 'Gate, portal and shelf coverage for fixed readers.', 'Antennas decide where a fixed RFID reader can see tags. Circular-polarized antennas read tags in any orientation; linear antennas reach further when tag direction is known.

Indoor and outdoor models are available for wall, ceiling or pole mounting at gates, portals, dock doors and shelves. Tell us the area you need to cover and we will suggest the right antennas and number of reader ports.', '[{"label":"Frequency","value":"UHF 860-960 MHz"},{"label":"Polarization","value":"Circular or linear"},{"label":"Mounting","value":"Wall, ceiling or pole"},{"label":"Use","value":"Indoor and outdoor models"}]'::jsonb, '[]'::jsonb, null, 18, '', 0, 1, true, false, false, 'UHF RFID Antennas – Circular & Linear | Prosper', 'UHF RFID antennas for fixed readers: circular or linear polarization, indoor and outdoor models, wall, ceiling or pole mount. Delivery in India.'),
  ('PI-RDR-004', 'antenna-integrated-rfid-reader', 'Integrated RFID Reader with GPS and 4G', 'Prosper Infotech', (select id from categories where slug = 'readers-antennas'), 'RFID, GPS and 4G LTE in a single standalone device. Coming soon.', 'This all-in-one device combines a UHF RFID reader, a built-in antenna, GPS and a 4G LTE connection in a single housing. It suits vehicles, remote gates and sites where there is no network cable, because it reads tags and reports their location on its own.

The reader is coming soon. Request a price to be told when it is available or to plan a pilot.', '[{"label":"Radios","value":"UHF RFID, GPS, 4G LTE"},{"label":"Antenna","value":"Built in"},{"label":"Use","value":"Vehicles, gates and remote sites"},{"label":"Status","value":"Coming soon"}]'::jsonb, '[]'::jsonb, null, 18, '', 0, 1, true, false, true, 'Integrated RFID Reader with GPS & 4G | Prosper Infotech', 'All-in-one UHF RFID reader with built-in antenna, GPS and 4G LTE for vehicles, gates and remote sites. Coming soon. Request a price.'),
  ('PI-SCN-001', 'handheld-barcode-scanner', 'Wired Handheld Barcode Scanner (1D / 2D / QR)', 'Prosper Infotech', (select id from categories where slug = 'barcode-scanners'), 'Billing counters, stores, stock rooms and dispatch desks.', 'A wired handheld scanner is the simplest way to read barcodes at a desk or counter. Plug it into a USB port and it works like a keyboard, typing the code into whatever program is open, so no software is needed.

It reads 1D barcodes, 2D codes and QR codes, and has a drop-resistant housing for daily use at billing counters, stores, stock rooms and dispatch desks.', '[{"label":"Reads","value":"1D barcodes, 2D codes and QR"},{"label":"Connection","value":"USB wired"},{"label":"Use","value":"Plug and play, works like a keyboard"},{"label":"Build","value":"Drop resistant housing"}]'::jsonb, '[]'::jsonb, null, 18, '', 0, 1, true, true, false, 'Wired Handheld Barcode Scanner – 1D, 2D, QR | Prosper', 'Plug-and-play USB handheld barcode scanner that reads 1D barcodes, 2D codes and QR. Drop-resistant, for billing counters and stock rooms.'),
  ('PI-SCN-002', 'wireless-barcode-scanner', 'Wireless Barcode Scanner (1D / 2D / QR)', 'Prosper Infotech', (select id from categories where slug = 'barcode-scanners'), 'Warehouses, shop floors and large counters where a cable gets in the way.', 'A wireless scanner removes the cable, so staff can scan large or heavy items where they sit instead of carrying them to the counter. It connects over Bluetooth or a 2.4 GHz receiver and reads 1D barcodes, 2D codes and QR codes.

The rechargeable battery lasts a full shift, and the charging cradle extends the working range in warehouses, shop floors and large counters.', '[{"label":"Reads","value":"1D barcodes, 2D codes and QR"},{"label":"Connection","value":"Bluetooth or 2.4 GHz wireless"},{"label":"Battery","value":"Rechargeable, full-shift use"},{"label":"Range","value":"Long range with charging cradle"}]'::jsonb, '[]'::jsonb, null, 18, '', 0, 1, true, false, false, 'Wireless Barcode Scanner – Bluetooth, 1D/2D/QR | Prosper', 'Cordless barcode scanner with Bluetooth or 2.4 GHz, rechargeable full-shift battery and charging cradle. Reads 1D, 2D and QR codes.'),
  ('PI-SCN-003', 'mobile-computer-with-barcode-scanner', 'Android Mobile Computer with Barcode Scanner', 'Prosper Infotech', (select id from categories where slug = 'barcode-scanners'), 'Stock counts, picking, proof of delivery and field audits.', 'A mobile computer puts a barcode scanner, touch screen and apps in one rugged device, so staff can scan and record work wherever they are. It suits picking, stock counts, proof of delivery and field audits.

It runs Android with a built-in 1D/2D imager and camera, connects over Wi-Fi, Bluetooth, 4G and NFC, and is built to survive drops and dust.', '[{"label":"Platform","value":"Android handheld with touch screen"},{"label":"Scanner","value":"Built-in 1D / 2D imager and camera"},{"label":"Connectivity","value":"Wi-Fi, Bluetooth, 4G, NFC"},{"label":"Build","value":"Rugged, drop and dust resistant"}]'::jsonb, '[]'::jsonb, null, 18, '', 0, 1, true, false, false, 'Android Mobile Computer with Barcode Scanner | Prosper', 'Rugged Android handheld with built-in 1D/2D barcode scanner, camera, Wi-Fi, Bluetooth, 4G and NFC for picking, stock counts and delivery.'),
  ('PI-SCN-004', 'fixed-mount-barcode-scanner', 'Fixed-Mount Barcode Scanner', 'Prosper Infotech', (select id from categories where slug = 'barcode-scanners'), 'Conveyors, sorting lines, kiosks and gates that scan without anyone holding it.', 'A fixed-mount scanner reads barcodes automatically as items pass, so nobody needs to hold a scanner. It is used on conveyors, sorting lines, kiosks and gates for continuous, hands-free scanning.

It reads 1D barcodes, 2D codes and QR codes, mounts on a bracket or in a tunnel, and connects over USB, RS-232 or Ethernet.', '[{"label":"Reads","value":"1D barcodes, 2D codes and QR"},{"label":"Mounting","value":"Bracket or tunnel mount"},{"label":"Connection","value":"USB, RS-232 or Ethernet"},{"label":"Use","value":"Hands-free, continuous scanning"}]'::jsonb, '[]'::jsonb, null, 18, '', 0, 1, true, false, false, 'Fixed-Mount Barcode Scanner for Conveyors | Prosper', 'Hands-free fixed-mount barcode scanner for conveyors, sorting lines, kiosks and gates. Reads 1D, 2D and QR. USB, RS-232 or Ethernet.'),
  ('PI-SCN-005', 'tabletop-barcode-scanner', 'Tabletop Barcode and QR Scanner', 'Prosper Infotech', (select id from categories where slug = 'barcode-scanners'), 'Retail counters, pharmacies and self-service desks.', 'A tabletop scanner sits on the counter and reads codes held in front of it, which keeps both hands free and speeds up checkout. It reads 1D barcodes, 2D codes and QR codes, including codes shown on a phone screen such as UPI and e-tickets.

It connects over USB and suits retail counters, pharmacies and self-service desks.', '[{"label":"Reads","value":"1D barcodes, 2D codes and QR, including phone screens"},{"label":"Mode","value":"Hands-free, with stand"},{"label":"Connection","value":"USB"},{"label":"Use","value":"Fast scanning at the counter"}]'::jsonb, '[]'::jsonb, null, 18, '', 0, 1, true, false, false, 'Tabletop Barcode & QR Scanner for Counters | Prosper', 'Hands-free tabletop scanner for retail counters and pharmacies. Reads 1D, 2D and QR codes, including from phone screens. USB connection.'),
  ('PI-PRN-001', 'desktop-rfid-printer-encoder', 'Desktop UHF RFID Printer and Encoder', 'Prosper Infotech', (select id from categories where slug = 'printers-encoders'), 'Small batches of labels printed and encoded at the desk.', 'A desktop RFID printer prints the label and writes the RFID chip in one pass, so every label is ready to use the moment it comes out. It suits offices and small warehouses that tag items in batches every day.

It prints by thermal transfer, encodes UHF EPC Gen2 chips and connects over USB and Ethernet.', '[{"label":"Printing","value":"Thermal transfer"},{"label":"Encoding","value":"UHF EPC Gen2"},{"label":"Volume","value":"Low to medium daily use"},{"label":"Connectivity","value":"USB and Ethernet"}]'::jsonb, '[]'::jsonb, null, 18, '', 0, 1, true, false, false, 'Desktop UHF RFID Printer & Encoder | Prosper Infotech', 'Desktop thermal-transfer printer that prints and encodes UHF EPC Gen2 RFID labels. USB and Ethernet. For low to medium daily volumes.'),
  ('PI-PRN-002', 'industrial-rfid-printer-encoder', 'Industrial UHF RFID Printer and Encoder', 'Prosper Infotech', (select id from categories where slug = 'printers-encoders'), 'High-volume tagging in warehouses and production lines.', 'An industrial RFID printer is built for high volumes and all-day use in warehouses and production lines, where a desktop printer would wear out. It prints by thermal transfer and encodes UHF EPC Gen2 chips in the same pass.

It connects over USB and Ethernet, with optional Wi-Fi.', '[{"label":"Printing","value":"Thermal transfer, rugged build"},{"label":"Encoding","value":"UHF EPC Gen2"},{"label":"Volume","value":"High, all-day use"},{"label":"Connectivity","value":"USB, Ethernet, optional Wi-Fi"}]'::jsonb, '[]'::jsonb, null, 18, '', 0, 1, true, false, false, 'Industrial UHF RFID Printer & Encoder | Prosper Infotech', 'Rugged industrial RFID printer-encoder for high-volume, all-day UHF label printing in warehouses and production lines. USB and Ethernet.'),
  ('PI-PRN-003', 'barcode-label-printer', 'Thermal Barcode Label Printer', 'Prosper Infotech', (select id from categories where slug = 'printers-encoders'), 'Asset labels, shipping labels and shelf labels with barcodes and QR codes.', 'A barcode label printer makes asset labels, shipping labels and shelf labels with barcodes, QR codes, text and logos. It prints by thermal transfer for long-lasting labels or direct thermal for short-life labels.

Desktop to industrial models are available, all connecting over USB and Ethernet.', '[{"label":"Printing","value":"Thermal transfer or direct thermal"},{"label":"Codes","value":"Barcodes, QR codes, text and logos"},{"label":"Volume","value":"Desktop to industrial models"},{"label":"Connectivity","value":"USB and Ethernet"}]'::jsonb, '[]'::jsonb, null, 18, '', 0, 1, true, true, false, 'Thermal Barcode Label Printer – Desktop | Prosper', 'Thermal-transfer and direct-thermal barcode label printer for asset, shipping and shelf labels with barcodes, QR codes and logos.'),
  ('PI-PRN-004', 'blank-rfid-labels-and-ribbons', 'Blank RFID Labels and Thermal Ribbons', 'Prosper Infotech', (select id from categories where slug = 'printers-encoders'), 'Consumables for your RFID printer, in the sizes you need.', 'Consumables for RFID and barcode printers: printable RFID inlay labels and thermal-transfer ribbons in wax or resin. Wax ribbons suit paper labels; resin gives a tougher print on synthetic labels.

Custom label sizes are available on request, supplied in bulk rolls.', '[{"label":"Labels","value":"Printable RFID inlay labels"},{"label":"Ribbons","value":"Wax and resin options"},{"label":"Sizes","value":"Custom sizes on request"},{"label":"Supply","value":"Rolls, in bulk"}]'::jsonb, '[]'::jsonb, null, 18, '', 0, 1, true, false, false, 'Blank RFID Labels & Thermal Printer Ribbons | Prosper', 'Printable blank UHF RFID inlay labels and wax or resin thermal-transfer ribbons for RFID printers. Custom sizes, supplied in bulk rolls.'),
  ('PI-EDG-001', 'ai-edge-box', 'AI Edge Box (NVIDIA Jetson Orin NX)', 'Prosper Infotech', (select id from categories where slug = 'edge-iot'), 'On-site AI computing for cameras and vision projects. Powered by NVIDIA Jetson Orin NX.', 'The AI Edge Box runs vision AI next to your cameras instead of in the cloud, which keeps video on site and gives instant results. It is built on the NVIDIA Jetson Orin NX and handles several IP cameras for tasks such as OCR, number-plate recognition (ANPR) and object detection.

It is sold as part of a project, with set-up by our engineers.', '[{"label":"Processor","value":"NVIDIA Jetson Orin NX"},{"label":"Use","value":"Vision AI, OCR and ANPR at the edge"},{"label":"Inputs","value":"Multiple IP cameras"},{"label":"Sold as","value":"Part of a project, by quote"}]'::jsonb, '[]'::jsonb, null, 18, '', 0, 1, true, false, true, 'AI Edge Box – NVIDIA Jetson Orin NX | Prosper Infotech', 'On-site AI edge computer on NVIDIA Jetson Orin NX for vision AI, OCR and ANPR with multiple IP cameras. Sold with set-up support.'),
  ('PI-EDG-002', 'iot-gateway', 'Industrial IoT Gateway', 'Prosper Infotech', (select id from categories where slug = 'edge-iot'), 'Industrial edge gateway that connects sensors, PLCs and readers to your software.', 'An IoT gateway collects data from sensors, PLCs and RFID readers on site and sends it to your software. This industrial gateway is built on the Raspberry Pi CM4/CM5 and connects over Ethernet, Wi-Fi, 4G and RS-485.

It is sold as part of a project, with set-up by our engineers.', '[{"label":"Platform","value":"Raspberry Pi CM4 / CM5"},{"label":"Connectivity","value":"Ethernet, Wi-Fi, 4G, RS-485"},{"label":"Use","value":"Sensors, PLCs and RFID readers"},{"label":"Sold as","value":"Part of a project, by quote"}]'::jsonb, '[]'::jsonb, null, 18, '', 0, 1, true, false, true, 'Industrial IoT Gateway – Raspberry Pi CM4/CM5 | Prosper', 'Industrial edge gateway on Raspberry Pi CM4/CM5 that connects sensors, PLCs and RFID readers to your software. Ethernet, Wi-Fi, 4G, RS-485.')
on conflict (sku) do nothing;

